const STEP_ORDER = ["poseDescribe", "mediaChoice", "submit", "details", "motivation", "about"];

function StepProgress({ screen }) {
  const index = STEP_ORDER.indexOf(screen);
  if (index === -1) return null;
  const pct = ((index + 1) / STEP_ORDER.length) * 100;
  return (
    <div className="w-full rounded-full mb-8" style={{ height: 3, backgroundColor: "rgba(242,237,230,0.1)" }}>
      <div
        style={{
          width: `${pct}%`,
          height: 3,
          borderRadius: 999,
          backgroundColor: LANDING_TERRACOTTA,
          transition: "width 0.4s ease",
        }}
      />
    </div>
  );
}

